section.sourcecode:
module example-foo {
  namespace "tag:example.com,2017:example-foo";
  prefix f;

  container foo;
}

module example-bar {
  namespace "tag:example.com,2017:example-bar";
  prefix b;

  typedef foo { type uint32; }
}

module example-one {
  namespace "tag:example.com,2017:example-one";
  prefix one;
  import example-foo { prefix f; }
  import example-bar { prefix b; }

  augment "/f:foo" {
     leaf foo { type b:foo; }
  }
}

notification foo {
  leaf mtu {
    // when-stmtのコンテキストはこの通知なので不可
    when "/if:interfaces/if:interface[name='eth0']";
    type leafref {
      // path-stmtはコンテキストが異なるので可
      path "/if:interfaces/if:interface/if:mtu";
    }
  }
}

// 使用しない
when "md-name-format = 'name-format-null'";

// こちらが望ましい
when "derived-from-or-self(md-name-format, 'name-format-null')";

augment "/rt:active-route/rt:input/rt:destination-address" {
   when "rt:address-family='v4ur:ipv4-unicast'" {
     description
       "This augment is valid only for IPv4 unicast.";
   }
   // このaugment-stmtの中で定義されたノードは
   // when-stmtで参照できない
}

when /foo/services/*/active {
  description
    "No services directly defined in this module.
     Matches objects that have augmented the services container.";
}

leaf foo1 {
  type enumeration {
     enum one;
     enum two;
     enum three;
  }
}

leaf foo2 {
  // 誤り
  must "/f:foo1 != 'two'";
  type string;
}

leaf foo2 {
  // 正しい
  must "/f:foo1 = 'one' or /f:foo1 = 'three'";
  type string;
}

leaf foo1 {
  type enumeration {
     enum one;
     enum two;
     enum three;
     enum four;
  }
}

import ietf-yang-types {
   prefix yang;
   reference "RFC 6991: Common YANG Data Types";
}

leaf reserved {
  type string;
  description
    "This object has no purpose at this time, but a future
     revision of this module might define a purpose
     for this object.";
  }
}

revision "2012-02-22" {
  description
    "Initial version";
  reference
    "RFC 8341: Network Configuration
               Access Control Model";
}

revision "2017-12-11" {
  description
    "Added support for YANG 1.1 actions and notifications tied to
     data nodes.  Clarify how NACM extensions can be used by other
     data models.";
  reference
    "RFC 8407: Network Configuration Protocol (NETCONF)
               Access Control Model";
}

revision "2012-02-22" {
  description
    "Initial version";
  reference
    "RFC 8341: Network Configuration
               Access Control Model";
}

leaf foo {
  type enumeration {
    enum one;
    enum two;
  }
}

identity foo-type {
  description "Base for the extensible type";
}

identity one {
  base f:foo-type;
}
identity two {
  base f:foo-type;
}

leaf foo {
  type identityref {
    base f:foo-type;
  }
}

typedef ipv4-address-no-zone {
  type inet:ipv4-address {
    pattern '[0-9\.]*';
  }
  ...
}

typedef yang-identifier {
  type string {
    length "1..max";
    pattern '[a-zA-Z_][a-zA-Z0-9\-_.]*';
    pattern '.|..|[^xX].*|.[^mM].*|..[^lL].*';
  }
  ...
}

typedef dscp {
  type uint8 {
     range "0..63";
  }
  ...
}

leaf foo {
  // 誤り
  type enumeration {
    enum one;
    enum two;
  }
  description
    "The foo enum...
     one: The first enum
     two: The second enum";
}

leaf foo {
  // 正しい
  type enumeration {
    enum one {
      description "The first enum";
    }
    enum two {
      description "The second enum";
    }
  }
  description
    "The foo enum...  ";
}

type union {
  type string;
  type enumeration {
    enum up;
    enum down;
  }
}

type union {
  type enumeration {
    enum up;
    enum down;
  }
  type string;
}

type union {
  type string;
  type int32;
}

type union {
  type int32;
  type string;
}

leaf flag1 {
  type empty;
}

leaf flag2 {
  type boolean;
  default false;
}

container top {
   container foos {
      list foo { ... }
   }
   container bars {
      list bar { ... }
   }
}

container top {
   list foo { ... }
   list bar { ... }
}

notification interface-up {
  description "Sent when an interface is activated.";
  leaf name {
    type leafref {
      path "/if:interfaces/if:interface/if:name";
    }
  }
}

feature feature1 {
  description "Some protocol feature";
}

feature feature2 {
  if-feature "feature1";
  description "Another protocol feature";
}

augment "/if:interfaces/if:interface" {
    when "if:type = 'ianaift:ethernetCsmacd'";

    container ethernet {
        leaf duplex {
            ...
        }
    }
}

module example-module {

  yang-version 1.1;
  namespace "tag:example.com,2017:example-module";
  prefix mymod;

  import iana-if-type { prefix iana; }
  import ietf-interfaces { prefix if; }

  identity some-new-iftype {
     base iana:iana-interface-type;
  }

  augment "/if:interfaces/if:interface" {
     when "if:type = 'mymod:some-new-iftype'";

     leaf mandatory-leaf {
        type string;
        mandatory true;
     }
  }
}

container backups {
  list backup {
     ...
     max-elements  10;
     ...
  }
}

deviation /bk:backups/bk:backup {
  deviate add {
     max-elements  10;
  }
}

list foo {
   key name;
   leaf name {
     type string;
   }
   ...
}

list foo-addon {
   key name;
   config false;
   leaf name {
     type string;
   }
   ...
}

list foo {
   key name;
   leaf name {
     type string;
   }
   ...
}

list foo-addon {
   key name;
   config false;
   leaf name {
     type leafref {
       path "/foo/name";
       require-instance false;
     }
   }
   leaf addon {
     type string;
     mandatory true;
   }
}

container foo {
  ...
  // "config true"のノードと、対応する"config true"の
  // オブジェクトを持たない"config false"のノード（たとえば
  // カウンター）を含む
}

 module example-foo {
   namespace "urn:example.com:params:xml:ns:yang:example-foo";
   prefix "foo";

   container foo {
     // 設定データの子ノード
     // 運用値は運用状態データストアにのみ存在
     // 必要に応じて"config false"のノードを含めてもよい
   }
}

 module example-foo {
   namespace "urn:example.com:params:xml:ns:yang:example-foo";
   prefix "foo";

   container foo {
     // 設定データの子ノード
   }

   container foo-state {
     config false;
     // 運用状態の子ノード
   }
}

 module example-foo {
   namespace "urn:example.com:params:xml:ns:yang:example-foo";
   prefix "foo";

   container foo {
     // 設定データの子ノード
     // 運用値は運用状態データストアにのみ存在
     // 必要に応じて"config false"のノードを含めてもよい
     // 古いfoo-stateのデータノードをすべて含む
   }

   // 元のfoo-stateは残すが、statusをdeprecatedに変更する
   container foo-state {
     config false;
     status deprecated;
     // 運用状態の子ノード
   }
}

 module example-foo-state {
   namespace "urn:example.com:params:xml:ns:yang:example-foo-state";
   prefix "foo-s";

   // 新規または変換後のモジュールをインポート（この例では未使用）
   import example-foo { prefix foo; }

   container foo-state {
     config false;
     status deprecated;
     // 運用状態の子ノード
   }
}

rpc reset {
  input {
    leaf interface {
      type if:interface-ref;
      mandatory true;
      description "The interface to reset.";
    }
  }
}

container interfaces {
  list interface {
    ...
    action reset { }
  }
}

module ietf-template {
  yang-version 1.1;

  // この文字列を一意な名前空間URNの値に置き換える

  namespace "urn:ietf:params:xml:ns:yang:ietf-template";

  // この文字列を置き換え、一意なプレフィックスを選ぶようにする

  prefix temp;

  // ここにimportステートメントを書く。たとえば
  // import ietf-yang-types { prefix yang; }
  // import ietf-inet-types { prefix inet; }
  // 該当する場合はIETFのワーキンググループを明記する

  organization
    "IETF NETMOD (NETCONF Data Modeling Language) Working Group";

  // このcontactステートメントを自分の情報で更新する

  contact
    "WG Web:   <http://datatracker.ietf.org/wg/your-wg-name/>
     WG List:  <mailto:your-wg-name@ietf.org>

     Editor:   your-name
               <mailto:your-email@example.com>";

  // このdescriptionステートメントの最初の文を置き換える。
  // この文書の発行以降に著作権表示が更新されている場合は、
  // 最新のバージョンに置き換える

  description
    "This module defines a template for other YANG modules.

     Copyright (c) <insert year> IETF Trust and the persons
     identified as authors of the code.  All rights reserved.

     Redistribution and use in source and binary forms, with or
     without modification, is permitted pursuant to, and subject
     to the license terms contained in, the Simplified BSD License
     set forth in Section 4.c of the IETF Trust's Legal Provisions
     Relating to IETF Documents
     (http://trustee.ietf.org/license-info).

     This version of this YANG module is part of RFC XXXX; see
     the RFC itself for full legal notices.";

  // RFCエディターへ：XXXXを実際のRFC番号に置き換え、
  // この注記を削除してください

  // '2016-03-20'をモジュールの発行日に置き換える
  // 形式は（年-月-日）

  revision 2016-03-20 {
    description
      "what changed in this revision";
    reference "RFC XXXX: <Replace With Document Title>";
  }

  // extensionステートメント
  // featureステートメント
  // identityステートメント
  // typedefステートメント
  // groupingステートメント
  // データ定義ステートメント
  // augmentステートメント
  // rpcステートメント
  // notificationステートメント
  // 公開するモジュールにdeviationステートメントを置かないこと
}
